def source_of(fn):
    """Function source with its docstring removed (statements verbatim)."""
    src = textwrap.dedent(inspect.getsource(fn))
    tree = ast.parse(src)
    f = tree.body[0]
    f.returns = None
    for arg in f.args.args + f.args.kwonlyargs:
        arg.annotation = None
    if f.body and isinstance(f.body[0], ast.Expr) and isinstance(getattr(f.body[0], "value", None), ast.Constant) and isinstance(f.body[0].value.value, str):
        f.body = f.body[1:] or [ast.Pass()]
    return ast.unparse(tree)


def run_cold(code):
    """Execute code in an empty namespace; return (stdout, namespace)."""
    buf = io.StringIO()
    ns = {"__name__": "__listing__"}
    with contextlib.redirect_stdout(buf):
        exec(compile(code, "<listing>", "exec"), ns)
    return buf.getvalue(), ns


def listing(caption, path, fns, header, demo):
    """B: extracted unit + constants it needs, executed cold, with the REPL transcript of `demo`."""
    _listing[0] += 1
    unit = header.strip() + "\n\n" + "\n\n".join(source_of(f) for f in fns)
    out, _ = run_cold(unit + "\n\n" + demo)
    lines = unit.count("\n") + 1
    shown = unit + "\n\n" + demo
    return (f"**Listing {_listing[0]} — {caption}** (`{path}`; extracted, {lines} lines, executed cold)\n\n```python\n{shown}\n```\n\n"
            f"```\n{out.rstrip()}\n```\n")


def transcript(title, code):
    out, _ = run_cold(code)
    return f"**{title}**\n\n```\n" + "\n".join(f">>> {l}" if l.strip() and not l.startswith(" ") else l for l in code.strip().splitlines()) + f"\n{out.rstrip()}\n```\n"


def psi(seed):
    r = random.Random(seed)
    return [complex(r.gauss(0, 1), r.gauss(0, 1)) for _ in range(16)]


